var spell = struct { // side table: one entry per subject
	sync.Mutex
	m map[*Document]*spellState
}{m: map[*Document]*spellState{}}

func attachSpell(d *Document) *spellState {
	spell.Lock()
	defer spell.Unlock()
	if _, ok := spell.m[d]; !ok {
		spell.m[d] = &spellState{}
	}
	return spell.m[d]
}
